import openpyxl
wb = openpyxl.load_workbook('budget.xlsx', data_only=False)
ws = wb['Budget']
for coord in ['B8','C8','B23','C23','B25','C25','C11','C22']:
    c = ws[coord]
    print(coord, repr(c.value))
print('--- all formulas ---')
for row in ws.iter_rows():
    for c in row:
        if isinstance(c.value, str) and c.value.startswith('='):
            print(c.coordinate, c.value)
